"""Vendor pinned Leaflet assets into flash; no network dependency at runtime."""
import gzip
import hashlib
import json
from pathlib import Path
import requests

root = Path(__file__).resolve().parents[1]
dest = root / 'src' / 'vendor' / 'leaflet'
dest.mkdir(parents=True, exist_ok=True)
base = 'https://unpkg.com/leaflet@1.9.4/'
assets = {'leaflet.js': 'dist/leaflet.js', 'leaflet.css': 'dist/leaflet.css', 'LICENSE': 'LICENSE'}
manifest = {'version': '1.9.4', 'source': base, 'sha256': {}}
blocks = ['// Generated by tools/vendor_leaflet.py. Leaflet 1.9.4, BSD-2-Clause; see vendor/leaflet/LICENSE.', '#pragma once']
for name, remote in assets.items():
    response = requests.get(base + remote, timeout=60)
    response.raise_for_status()
    content = response.content
    if name == 'leaflet.js':
        content = content.replace(b'//# sourceMappingURL=leaflet.js.map', b'')
    (dest / name).write_bytes(content)
    manifest['sha256'][name] = hashlib.sha256(content).hexdigest()
    if name == 'LICENSE':
        continue
    compressed = gzip.compress(content, mtime=0)
    symbol = name.replace('.', '_') + '_gz'
    blocks.append(f'static const uint8_t {symbol}[] PROGMEM = {{')
    blocks.extend('  ' + ','.join(f'0x{n:02x}' for n in compressed[i:i+24]) + ',' for i in range(0, len(compressed), 24))
    blocks.append('};')
    print(name, len(content), 'gzip', len(compressed))
(dest / 'manifest.json').write_text(json.dumps(manifest, indent=2) + '\n', encoding='utf-8')
(root / 'src' / 'WebMapAssets.h').write_text('\n'.join(blocks) + '\n', encoding='utf-8')
